import{_ as o,C as n,o as a,c as l,a2 as d,b as i,w as t,a as c,E as u,a3 as p}from"./chunks/framework.DZUUNQ77.js";const _=JSON.parse('{"title":"BundleCompat · Bundle 兼容","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helper/compat/bundle-compat.md","filePath":"reference/helper/compat/bundle-compat.md","lastUpdated":1784063681000}'),s={name:"reference/helper/compat/bundle-compat.md"};function B(m,e,h,b,C,E){const r=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=d('<h1 id="bundlecompat-·-bundle-兼容" tabindex="-1">BundleCompat · Bundle 兼容 <a class="header-anchor" href="#bundlecompat-·-bundle-兼容" aria-label="Permalink to &quot;BundleCompat · Bundle 兼容&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/helper/compat/BundleCompat.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/helper/compat/BundleCompat.java</code></a></p></div><p><code>BundleCompat</code> 解决一个核心需求：<strong>把 <code>IBinder</code> 句柄塞进 <code>Bundle</code> 跨进程传递，再从另一端取出来</strong>。这是 <a href="./../../../features/ipc-bridge">IPC 桥</a> 跨进程传 binder 的关键。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>getBinder(Bundle bundle, String key)</code></td><td>从 Bundle 取出先前放入的 <code>IBinder</code></td></tr><tr><td><code>putBinder(Bundle bundle, String key, IBinder value)</code></td><td>把 <code>IBinder</code> 放进 Bundle</td></tr><tr><td><code>clearParcelledData(Bundle bundle)</code></td><td>清理 Bundle 内部的 Parcel 数据（释放内存）</td></tr></tbody></table><h2 id="为什么需要它" tabindex="-1">为什么需要它 <a class="header-anchor" href="#为什么需要它" aria-label="Permalink to &quot;为什么需要它&quot;">​</a></h2><p><code>Bundle</code> 不直接支持 <code>IBinder</code> 类型（<code>putBinder</code> 是隐藏 API <code>Bundle.putIBinder</code>/<code>getIBinder</code>）。但跨进程传 binder 是 VirtualXposed 的命脉——client 通过 <code>ContentProvider.call</code> 向 server 取服务 binder 时，binder 句柄就是放在返回 <code>Bundle</code> 里传回来的。本类用反射调隐藏方法实现。</p><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p><a href="./../../../features/ipc-bridge">IPC 桥</a> 的 <code>BinderProvider.call(&quot;@&quot;)</code> 用 <code>BundleCompat.putBinder</code> 把 <code>ServiceFetcher</code> IBinder 放进返回的 Bundle，客户端用 <code>getBinder</code> 取出。后续所有 <code>V*Manager</code> 跨进程调用都建立在这条通道上。</p><h2 id="binder-跨进程传递流" tabindex="-1">binder 跨进程传递流 <a class="header-anchor" href="#binder-跨进程传递流" aria-label="Permalink to &quot;binder 跨进程传递流&quot;">​</a></h2>',10)),(a(),i(p,null,{default:t(()=>[u(r,{id:"mermaid-67",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20CL%20as%20client%0A%20%20participant%20CP%20as%20BinderProvider.call(%22%40%22)%0A%20%20participant%20BC%20as%20BundleCompat%0A%20%20participant%20SRV%20as%20server%20(ServiceFetcher)%0A%20%20CL-%3E%3ECP%3A%20query%2Fcall%20%E5%8F%96%E6%9C%8D%E5%8A%A1%0A%20%20SRV-%3E%3EBC%3A%20putBinder(bundle%2C%20key%2C%20serviceBinder)%0A%20%20Note%20over%20BC%3A%20%E5%8F%8D%E5%B0%84%E8%B0%83%E9%9A%90%E8%97%8F%20Bundle.putIBinder%0A%20%20CP--%3E%3ECL%3A%20%E8%BF%94%E5%9B%9E%20Bundle%0A%20%20CL-%3E%3EBC%3A%20getBinder(bundle%2C%20key)%0A%20%20Note%20over%20BC%3A%20%E5%8F%8D%E5%B0%84%E8%B0%83%E9%9A%90%E8%97%8F%20Bundle.getIBinder%0A%20%20BC--%3E%3ECL%3A%20IBinder%20%E5%8F%A5%E6%9F%84%0A%20%20CL-%3E%3ECL%3A%20%E8%BD%AC%E6%88%90%20V*Manager%20%E6%8E%A5%E5%8F%A3%E8%B0%83%E7%94%A8%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=d('<h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="./../../../features/ipc-bridge">IPC 桥</a>：核心使用场景。</li><li><a href="./content-provider-compat"><code>ContentProviderCompat</code></a>：<code>call</code> 的载体。</li><li><a href="./../../client/ipc">client/ipc</a>。</li></ul>',2))])}const f=o(s,[["render",B]]);export{_ as __pageData,f as default};
